    private fun supplement(
        id: String,
        name: String,
        benefit: String,
        evidence: String,
        whatKnown: String,
        timing: String,
        caution: String,
        sources: List<ContentSource>
    ) = SupplementGuideItem(
        id = id,
        name = name,
        dosageAndForm = "Не назначайте дозировку самостоятельно. Применение и обследование обсуждаются с врачом.",
        primaryBenefit = benefit,
        mechanismOfAction = whatKnown,
        timingAdvice = timing,
        cautionNote = caution,
        evidenceStrength = evidence,
        sources = sources
    )

