        supplement("supp_zinc", "Цинк", "Необходимый минерал; добавка — при установленной потребности", "Дефицит возможен; польза для лечения AUD не установлена.", "Цинк обычно получают с пищей. Длительное тяжёлое употребление и неполноценное питание могут повышать риск дефицита, но добавка не доказана как средство от тяги, абстиненции или нарушений сна.", "Обсудите возможный дефицит и лекарства с врачом или фармацевтом.", "Избыток может вызывать тошноту и мешать усвоению меди; возможны взаимодействия с некоторыми антибиотиками и пеницилламином. Не лечит алкогольную абстиненцию.", listOf(ContentSource("NIH ODS: Zinc", "https://ods.od.nih.gov/factsheets/Zinc-HealthProfessional/"), ContentSource("WHO: Management of alcohol withdrawal", "https://www.who.int/teams/mental-health-and-substance-use/treatment-care/mental-health-gap-action-programme/evidence-centre/alcohol-use-disorders/management-of-alcohol-withdrawal"), ContentSource("Randomized zinc trial in heavy alcohol use", "https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2765686"))),
