    val motivationalItems: List<MotivationalItem> = buildList {
        firstSteps.forEachIndexed { index, copy ->
            add(MotivationalItem(
                id = "msg_curated_${index + 1}",
                category = MotivationCategory.DAILY_MESSAGE,
                title = copy.title,
                authorOrHero = "Редакция «Ясный Берег»",
                authorRoleOrAge = "Авторское послание поддержки",
                content = copy.text,
                practicalTakeaway = copy.step,
                minSoberDays = 0,
                maxSoberDays = 3650,
                targetEmotions = copy.emotions,
                subCategoryTag = if (copy.emotions.contains(EmotionalState.CRISIS)) "Трудный момент" else "Послание дня"
            ))
        }
        editorialThoughts.forEachIndexed { index, thought ->
            add(MotivationalItem(
                id = "thought_original_${index + 1}",
                category = MotivationCategory.FAMOUS_QUOTE,
                title = listOf("Мысль для опоры", "Напоминание себе", "Короткая пауза")[index % 3],
                authorOrHero = "Редакция «Ясный Берег»",
                authorRoleOrAge = "Авторский текст, не историческая цитата",
                content = thought,
                practicalTakeaway = "Выберите один реальный следующий шаг и, если нужно, попросите поддержки.",
                minSoberDays = 0,
                maxSoberDays = 3650,
                targetEmotions = setOf(EmotionalState.CALM, EmotionalState.PROUD, EmotionalState.ANXIOUS, EmotionalState.LONELY),
                subCategoryTag = "Мысль для поддержки"
            ))
        }
        compositeCases.forEachIndexed { index, case ->
            add(MotivationalItem(
                id = "case_composite_${index + 1}",
                category = MotivationCategory.REAL_STORY,
                title = listOf("Собирательный пример: попросить о помощи", "Собирательный пример: новый план", "Собирательный пример: маленький шаг")[index % 3],
                authorOrHero = "Обобщённый пример",
                authorRoleOrAge = "Не является реальным отзывом или историей пациента",
                content = case,
                practicalTakeaway = "В истории можно взять только тот шаг, который безопасен и подходит именно вам.",
                minSoberDays = 0,
                maxSoberDays = 3650,
                targetEmotions = setOf(EmotionalState.CRISIS, EmotionalState.ANXIOUS, EmotionalState.LONELY, EmotionalState.TIRED, EmotionalState.CALM),
                subCategoryTag = "Собирательные примеры"
            ))
        }
    }

    fun daypartForHour(hour: Int): DaypartSupport = when (hour.coerceIn(0, 23)) {
        in 5..10 -> DaypartSupport("Утро", "Начните без спешки", "Сегодня не нужно делать всё сразу. Выберите один посильный шаг и поддержку, которая вам подходит.", "Утренний шаг", "Посмотрите расписание дня и назначьте один разговор или дело, важное для вас.")
        in 11..16 -> DaypartSupport("День", "Вернитесь к своему плану", "Сделайте небольшую паузу и проверьте, не нужна ли вам сейчас поддержка, отдых или более спокойное место.", "Дневная пауза", "Напишите близкому или выполните короткую практику заземления, если она вам подходит.")
        else -> DaypartSupport("Вечер", "Пусть вечер будет безопасным", "Заранее выберите человека для связи и способ уйти из ситуации, где вам предлагают алкоголь.", "Вечерняя опора", "Подготовьте спокойное занятие и безопасный план на ближайший час.")
    }

    fun reminderFor(hour: Int, dayOfYear: Int): ReminderCopy {
        val daypart = daypartForHour(hour)
        val messages = motivationalItems.filter { it.category == MotivationCategory.DAILY_MESSAGE }
        val index = Math.floorMod(dayOfYear * 7 + hour, messages.size)
        val item = messages[index]
        return ReminderCopy(
            "Ясный Берег · ${daypart.label.lowercase()}",
            "${item.title}. ${item.content}\n\nСледующий шаг: ${item.practicalTakeaway}"
        )
    }
